Rules.InvariantScript:
Set(gblBootStep, "Starting");
Set(gblBootFailed, false);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
Set(gblActorUpn, User().Email);
Set(gblCfg, {PageSize: 50, BulkCap: 500, ReasonMin: 20, SuppressionMaxDays: 365});
Select(btnDoBootstrap)

Set(gblBootFailed, false);

// ---- 1. who am I, and what may I see ----
Set(gblBootStep, "Reading your access");
ClearCollect(colScope, Blank());
Clear(colScope);
IfError(
    ClearCollect(
        colScope,
        Filter(
        db_dq_sandbox.dquspGetMyScope({ActorUpn: gblActorUpn}).ResultSets.Table1,
            !IsBlank(RoleCode)
        )
    ),
    Set(gblBootFailed, true);
    Set(gblError, {IsVisible: true, Title: "Could not read your access", Detail: FirstError.Message})
);

// ---- 2. reference data. LookupName values are the real ones from
//         dq.Lookup: Severity, ExceptionStatus, Domain, SourceSystem,
//         StatusGroup, Role, TargetLayer, Dimension, TemporalPattern.
//         Each call is guarded so one bad lookup cannot halt the chain. ----
Set(gblBootStep, "Loading reference data");
IfError(
    ClearCollect(colLkSeverity, Filter(db_dq_sandbox.dquspGetLookup({ActorUpn: gblActorUpn, LookupName: "Severity"}).ResultSets.Table1, !IsBlank(Code))),
    Set(gblError, {IsVisible: true, Title: "Could not load severities", Detail: FirstError.Message})
);
IfError(
    ClearCollect(colLkStatus, Filter(db_dq_sandbox.dquspGetLookup({ActorUpn: gblActorUpn, LookupName: "ExceptionStatus"}).ResultSets.Table1, !IsBlank(Code))),
    Set(gblError, {IsVisible: true, Title: "Could not load statuses", Detail: FirstError.Message})
);
// The queue filters on StatusGroup (OPEN|RESOLVED|SUPPRESSED|ALL), which is
// its own lookup - NOT the per-exception ExceptionStatus list.
IfError(
    ClearCollect(colLkStatusGroup, Filter(db_dq_sandbox.dquspGetLookup({ActorUpn: gblActorUpn, LookupName: "StatusGroup"}).ResultSets.Table1, !IsBlank(Code))),
    Set(gblError, {IsVisible: true, Title: "Could not load status groups", Detail: FirstError.Message})
);
IfError(
    ClearCollect(colLkDomain, Filter(db_dq_sandbox.dquspGetLookup({ActorUpn: gblActorUpn, LookupName: "Domain"}).ResultSets.Table1, !IsBlank(Code))),
    Set(gblError, {IsVisible: true, Title: "Could not load domains", Detail: FirstError.Message})
);
IfError(
    ClearCollect(colLkSource, Filter(db_dq_sandbox.dquspGetLookup({ActorUpn: gblActorUpn, LookupName: "SourceSystem"}).ResultSets.Table1, !IsBlank(Code))),
    Set(gblError, {IsVisible: true, Title: "Could not load source systems", Detail: FirstError.Message})
);

// ---- 3. identity and domain scope ----
Set(gblBootStep, "Working out your scope");
Set(gblDisplayName, Coalesce(First(colScope).DisplayName, User().FullName, gblActorUpn));
Set(gblInitials, Upper(Left(Coalesce(gblDisplayName, gblActorUpn), 2)));
IfError(
    ClearCollect(
        gblDomains,
        Filter(
            colLkDomain As D,
            CountRows(Filter(colScope, IsBlank(DomainCode))) > 0
                || CountRows(Filter(colScope, DomainCode = D.Code)) > 0
        )
    ),
    Set(gblError, {IsVisible: true, Title: "Could not resolve your domains", Detail: FirstError.Message})
);

// ---- 4. counts and role flags ----
Set(gblBootStep, "Loading your work");
IfError(
    Set(gblMyWork, First(db_dq_sandbox.dquspGetMyWork({ActorUpn: gblActorUpn}).ResultSets.Table1)),
    Set(gblBootFailed, true);
    Set(gblError, {IsVisible: true, Title: "Could not load your work", Detail: FirstError.Message})
);
Set(gblIsAdmin, Coalesce(gblMyWork.IsAdmin, false));
Set(gblIsApprover, Coalesce(gblMyWork.IsApprover, false) || gblIsAdmin);
Set(gblIsSteward, CountRows(Filter(colScope, RoleCode = "STEWARD")) > 0 || gblIsApprover);

Set(gblBootStep, "Done");

// ---- 5. route. Only skipped when the two load-bearing calls failed,
//         and even then the user gets buttons rather than a dead screen. ----
If(
    !gblBootFailed,
    If(
        CountRows(colScope) = 0,
        Navigate(scrNoAccess),
        Navigate(scrMyWork)
    )
)
